INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('compendium-quiz-fis1-57755cae01c717d12766-option-1','compendium-quiz-fis1-57755cae01c717d12766','Pode ser observado em todas as células.',1,0),('compendium-quiz-fis1-57755cae01c717d12766-option-2','compendium-quiz-fis1-57755cae01c717d12766','A inativação de canais de sódio dependentes da voltagem é mais precoce do que o encerramento dos canais de potássio dependentes de voltagem.',2,1),('compendium-quiz-fis1-57755cae01c717d12766-option-3','compendium-quiz-fis1-57755cae01c717d12766','Os canais de potássio dependentes da voltagem são constituídos por 3 formas funcionais.',3,0),('compendium-quiz-fis1-57755cae01c717d12766-option-4','compendium-quiz-fis1-57755cae01c717d12766','O período refratário relativo é causado apenas devido ao menor número disponível de canais de sódio dependentes da voltagem.',4,0),('compendium-quiz-fis1-57755cae01c717d12766-option-5','compendium-quiz-fis1-57755cae01c717d12766','A hiperpolarização pós potencial depende diretamente da bomba Na+/K+.',5,0),('compendium-quiz-fis1-278cf27c4e130dd6f1eb-option-1','compendium-quiz-fis1-278cf27c4e130dd6f1eb','Redução do gradiente de concentração.',1,0),('compendium-quiz-fis1-278cf27c4e130dd6f1eb-option-2','compendium-quiz-fis1-278cf27c4e130dd6f1eb','Redução da temperatura.',2,0),('compendium-quiz-fis1-278cf27c4e130dd6f1eb-option-3','compendium-quiz-fis1-278cf27c4e130dd6f1eb','Aumento da distância ao longo da qual ocorre a difusão.',3,0),('compendium-quiz-fis1-278cf27c4e130dd6f1eb-option-4','compendium-quiz-fis1-278cf27c4e130dd6f1eb','Aumento da área de difusão.',4,1),('compendium-quiz-fis1-278cf27c4e130dd6f1eb-option-5','compendium-quiz-fis1-278cf27c4e130dd6f1eb','Aumento do raio da molécula.',5,0),('compendium-quiz-fis1-5ba0d7e2a6d1f54104a6-option-1','compendium-quiz-fis1-5ba0d7e2a6d1f54104a6','O aumento da temperatura.',1,0),('compendium-quiz-fis1-5ba0d7e2a6d1f54104a6-option-2','compendium-quiz-fis1-5ba0d7e2a6d1f5