INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('compendium-quiz-fis1-9395a2459d5536f6656f-option-1','compendium-quiz-fis1-9395a2459d5536f6656f','Quanto maior a lipossolubilidade de uma molécula, maior será o seu coeficiente de difusão e maior será a taxa de difusão através da membrana.',1,0),('compendium-quiz-fis1-9395a2459d5536f6656f-option-2','compendium-quiz-fis1-9395a2459d5536f6656f','Difusão é o movimento espacial e aleatório de átomos, moléculas ou partículas, determinado pela energia térmica da própria partícula.',2,0),('compendium-quiz-fis1-9395a2459d5536f6656f-option-3','compendium-quiz-fis1-9395a2459d5536f6656f','No transporte passivo de uma molécula, esta move-se a favor do seu gradiente eletroquímico.',3,0),('compendium-quiz-fis1-9395a2459d5536f6656f-option-4','compendium-quiz-fis1-9395a2459d5536f6656f','O transporte ativo secundário de uma molécula está diretamente acoplado à hidrólise de ATP.',4,1),('compendium-quiz-fis1-9395a2459d5536f6656f-option-5','compendium-quiz-fis1-9395a2459d5536f6656f','O movimento de iões através de canais iónicos é um exemplo de transporte passivo.',5,0),('compendium-quiz-fis1-29b098adf949e6e5c3f5-option-1','compendium-quiz-fis1-29b098adf949e6e5c3f5','A forma de um potencial de ação é específica de cada tipo de célula e reflete o seu tipo de especialização funcional.',1,0),('compendium-quiz-fis1-29b098adf949e6e5c3f5-option-2','compendium-quiz-fis1-29b098adf949e6e5c3f5','Células com potenciais de ação curtos estão habitualmente envolvidas em vias de sinalização rápidas.',2,0),('compendium-quiz-fis1-29b098adf949e6e5c3f5-option-3','compendium-quiz-fis1-29b098adf949e6e5c3f5','Em determinados tipos celulares, a forma do potencial de ação pode ser modificada por via hormonal.',3,0),('compendium-quiz-fis1-29b098adf949e6e5c3f5-option-4','compendium-quiz-fis1-29b098adf949e6e5c3f5','A modulação da forma e da frequência de um potencial de ação ocorre por vários mecanismos reguladores bioquímicos que atuam independentemente da ação de canais iónicos.',4,1),('compendium-quiz-fis1-29b098adf949e6e5c3f5-option-5','compendium-quiz-fis1-29b098adf949e6e5c3f5','Células com potenciais de ação prolongados habitualmente desenvolvem respostas de contração rítmicas e sustentadas.',5,0),('compendium-quiz-fis1-c84a846d9ce0589a1855-option-1','compendium-quiz-fis1-c84a846d9ce0589a1855','Vai ocorrer um segundo potencial de ação de menor amplitude.',1,0),('compendium-quiz-fis1-c84a846d9ce0589a1855-option-2','compendium-quiz-fis1-c84a846d9ce0589a1855','Vai ocorrer um segundo potencial de ação de amplitude normal.',2,0),('compendium-quiz-fis1-c84a846d9ce0589a1855-option-3','compendium-quiz-fis1-c84a846d9ce0589a1855','Vai ocorrer um segundo potencial de ação de amplitude normal, mas atrasado no tempo.',3,0),('compendium-quiz-fis1-c84a846d9ce0589a1855-option-4','compendium-quiz-fis1-c84a846d9ce0589a1855','A ocorrência de um novo potencial de ação irá depender da intensidade do estímulo.',4,0),('compendium-quiz-fis1-c84a846d9ce0589a1855-option-5','compendium-quiz-fis1-c84a846d9ce0589a1855','Não vai ocorrer um novo potencial de ação.',5,1),('compendium-quiz-fis1-b5552198f305618a8478-option-1','compendium-quiz-fis1-b5552198f305618a8478','A tropomiosina é uma proteína com um papel essencialmente estrutural que se estende continuamente entre dois discos Z do sarcómero.',1,0),('compendium-quiz-fis1-b5552198f305618a8478-option-2','compendium-quiz-fis1-b5552198f305618a8478','A troponina T interage simultaneamente com duas moléculas de tropomiosina, mantendo a sua integridade.',2,0),('compendium-quiz-fis1-b5552198f305618a8478-option-3','compendium-quiz-fis1-b5552198f305618a8478','A calmodulina serve de interface de interação entre a troponina C e a actina.',3,0),('compendium-quiz-fis1-b5552198f305618a8478-option-4','compendium-quiz-fis1-b5552198f305618a8478','A titina é uma proteína com papel essencialmente estrutural que se estende continuamente desde a linha M até ao disco Z do sarcómero.',4,1),('compendium-quiz-fis1-b5552198f305618a8478-option-5','compendium-quiz-fis1-b5552198f305618a8478','O complexo trimérico troponina serve de interface de interação entre a cabeça pesada da miosina e os filamentos de actina durante o ciclo das pontes cruzadas.',5,0);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('compendium-quiz-fis1-9fa4ee76192312cabe5b-option-1','compendium-quiz-fis1-9fa4ee76192312cabe5b','Uma contração isométrica decorre a tensão constante.',1,0),('compendium-quiz-fis1-9fa4ee76192312cabe5b-option-2','compendium-quiz-fis1-9fa4ee76192312cabe5b','Uma contração isotónica caracteriza-se pela ausência de variação do comprimento muscular.',2,0),('compendium-quiz-fis1-9fa4ee76192312cabe5b-option-3','compendium-quiz-fis1-9fa4ee76192312cabe5b','O Lo (ou Lmax) corresponde ao comprimento muscular onde a tensão passiva desenvolvida é máxima.',3,0),('compendium-quiz-fis1-9fa4ee76192312cabe5b-option-4','compendium-quiz-fis1-9fa4ee76192312cabe5b','A relação velocidade de encurtamento-tensão é importante para caracterizar contrações isotónicas.',4,1),('compendium-quiz-fis1-9fa4ee76192312cabe5b-option-5','compendium-quiz-fis1-9fa4ee76192312cabe5b','A tensão ativa desencadeada por um músculo não depende do seu comprimento inicial.',5,0),('compendium-quiz-fis1-16454061b05f4a1da56b-option-1','compendium-quiz-fis1-16454061b05f4a1da56b','A contração fásica permite o desenvolvimento de força com gastos energéticos mínimos;',1,1),('compendium-quiz-fis1-16454061b05f4a1da56b-option-2','compendium-quiz-fis1-16454061b05f4a1da56b','Representa mais de 20% da massa corporal;',2,0),('compendium-quiz-fis1-16454061b05f4a1da56b-option-3','compendium-quiz-fis1-16454061b05f4a1da56b','Está bastante dependente de forma direta do sistema nervoso voluntário;',3,0),('compendium-quiz-fis1-16454061b05f4a1da56b-option-4','compendium-quiz-fis1-16454061b05f4a1da56b','O retículo sarcoplasmático é a principal fonte de cálcio para a contração muscular;',4,0),('compendium-quiz-fis1-16454061b05f4a1da56b-option-5','compendium-quiz-fis1-16454061b05f4a1da56b','A calmodulina tem um papel menos importante no músculo liso do que no esquelético.',5,0),('compendium-quiz-fis1-bc12e53f5be8070b589c-option-1','compendium-quiz-fi